import{_ as i,c as a,o as s,ag as t}from"./chunks/framework.B-XtCDNB.js";const k=JSON.parse('{"title":"Introduction to Genie","description":"Introduction to Genie This guide is a general introduction to the Genie programming language and a walk-through of its syntax. It is a port of the official Genie tutorial that was previously hosted...","frontmatter":{},"headers":[],"relativePath":"genie/introduction.md","filePath":"genie/introduction.md","lastUpdated":1778786960000}'),n={name:"genie/introduction.md"};function l(o,e,r,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="introduction-to-genie" tabindex="-1">Introduction to Genie <a class="header-anchor" href="#introduction-to-genie" aria-label="Permalink to &quot;Introduction to Genie&quot;">​</a></h1><p>This guide is a general introduction to the Genie programming language and a walk-through of its syntax. It is a port of the official Genie tutorial that was previously hosted on the GNOME Wiki. The same material is split into chapters so you can read or link to smaller sections.</p><h2 id="what-is-genie" tabindex="-1">What is Genie? <a class="header-anchor" href="#what-is-genie" aria-label="Permalink to &quot;What is Genie?&quot;">​</a></h2><p>Genie is a programming language, in the same vein as <a href="https://vala.dev" target="_blank" rel="noreferrer">Vala</a>. Genie allows for a more modern programming style while being able to effortlessly create and use <a href="https://docs.gtk.org/gobject/" target="_blank" rel="noreferrer">GObjects</a> natively on Linux, *BSD, Windows or macOS.</p><p>The syntax is designed to be clean, clear and concise, and is derived from numerous modern languages like <a href="https://www.python.org/" target="_blank" rel="noreferrer">Python</a>, Boo, <a href="https://dlang.org/" target="_blank" rel="noreferrer">D</a> and <a href="https://en.wikipedia.org/wiki/Object_Pascal" target="_blank" rel="noreferrer">Object Pascal</a>.</p><p>Genie is very similar to Vala in functionality but differs in syntax, allowing the developer to use cleaner and less code to accomplish the same task.</p><p>Like Vala, Genie has the following advantages:</p><ul><li>Programs written in Genie have similar performance and resource usage to those written directly in Vala and C.</li><li>Genie produces C code that compiles to an executable binary. This means Genie has none of the bloat and overhead that comes with many other high-level languages which utilize a VM (e.g. Python, Mono, Java).</li><li>Classes in Genie are actually <a href="https://docs.gtk.org/gobject/" target="_blank" rel="noreferrer">GObjects</a>, so Genie can be used for creating platform code like widgets and libraries where GObjects are required for <a href="https://gi.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">binding to other languages</a>.</li></ul><h2 id="hello-world" tabindex="-1">Hello World <a class="header-anchor" href="#hello-world" aria-label="Permalink to &quot;Hello World&quot;">​</a></h2><p>As Hello World is the de facto first sample program, here is Genie&#39;s in all its glory:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello World&quot;</span></span></code></pre></div><p>Provided you have <a href="./../installation-guide.html">Vala installed</a>, copy and paste the code above and save it in a file called <code>hello.gs</code>. Genie code must be written in files with the <code>*.gs</code> extension.</p><p>Compile and run it by simply issuing the following on a UNIX-like command line in the same directory you saved <code>hello.gs</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> valac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.gs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./hello</span></span></code></pre></div><p>When you want to compile Genie code, you give the compiler a list of the files required, and the Genie/Vala compiler will work out how they fit together.</p><p>If you give <code>valac</code> the <code>-C</code> switch, it will create a C source code file called <code>hello.c</code> instead of an executable binary file.</p><h2 id="hello-world-explained" tabindex="-1">Hello World Explained <a class="header-anchor" href="#hello-world-explained" aria-label="Permalink to &quot;Hello World Explained&quot;">​</a></h2><p>As you can see, Genie is pretty clean and concise so the above example will not need much explaining.</p><h3 id="init-block" tabindex="-1">init Block <a class="header-anchor" href="#init-block" aria-label="Permalink to &quot;init Block&quot;">​</a></h3><p>An <code>init</code> block declared outside of a class or struct is equivalent to a <code>main</code> function in C and only one of these may be present. Any code that needs to be run at start up should be present here.</p><h3 id="block-indentation" tabindex="-1">Block Indentation <a class="header-anchor" href="#block-indentation" aria-label="Permalink to &quot;Block Indentation&quot;">​</a></h3><p>Block indentation in Genie uses tabs by default. So in the Hello World example above, a tab appears prior to the keyword <code>print</code>.</p><p>It is also possible to tell it to use a certain number of spaces in lieu of a tab by ensuring the first line of the source file contains the following attribute:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[indent=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  print</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello World&quot;</span></span></code></pre></div><p>That attribute tells Genie to ignore tabs and use 2 spaces to signify a block indentation. An <code>indent=0</code> means use a tab.</p><p>Code examples on this page use spaces for indentation because the original wiki converts tabs to spaces. When writing your own Genie programs use tabs unless you have set the <code>[indent=N]</code> attribute.</p><h3 id="case-and-unicode" tabindex="-1">Case and Unicode <a class="header-anchor" href="#case-and-unicode" aria-label="Permalink to &quot;Case and Unicode&quot;">​</a></h3><p>Genie is case sensitive, so be careful when mixing case in your code. Keywords are always lowercase. Identifiers can be mixed case, but must be in the Unicode U+0020 to U+007E range. This is the <a href="https://en.wikipedia.org/wiki/ASCII#Printable_characters" target="_blank" rel="noreferrer">ASCII printable characters</a> range as a result of it being compiled into C code. For example:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pi:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Math</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PI</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pi.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">to_string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>would compile, but</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    π:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Math</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PI</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> π.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">to_string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>would produce an error because the symbol <code>π</code> is outside the ASCII printable range of characters.</p><p>Genie can, however, handle Unicode data very well. Here is an example of Hello World with Unicode characters outside the ASCII range:</p><div class="language-genie vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">genie</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Intl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setlocale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LocaleCategory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ALL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    print</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello World! 你好世界&quot;</span></span></code></pre></div><p>C libraries use the US English, ASCII encoding, by default as part of the C standard. The <code>setlocale</code> command changes this to the locale of the machine and if this can handle Unicode and has Chinese glyphs installed then the Chinese version of Hello World will be displayed.</p><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><ol><li><a href="./introduction/01-compiling.html">Compiling and Genie&#39;s relation to C</a> — VAPI, build scripts, static checks, and generated C</li><li><a href="./introduction/02-language-basics.html">Language basics</a> — documentation style, identifiers, values, operators, control flow, scope</li><li><a href="./introduction/03-types-functions-and-errors.html">Types, functions, and errors</a> — delegates, classes, generics, functions, <code>try</code> / <code>except</code></li><li><a href="./introduction/04-objects.html">Objects</a> — fields, constructors, properties, methods, signals, inheritance</li><li><a href="./introduction/05-collections-and-interop.html">Collections and C interoperability</a> — operators, collections, C bindings</li><li><a href="./introduction/06-concurrency-and-systems.html">Concurrency, IPC, and system interfaces</a> — async, D-Bus, pipes, signals, UIs</li><li><a href="./introduction/07-advanced.html">Advanced topics</a> — attributes, memory, mixing Genie and Vala, further reading</li></ol>`,37)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
